(()=>{const dlg=document.querySelector("#incidentDialog"),form=document.querySelector("#incidentForm"),rows=document.querySelector("#incidentRows"),key="sshma-incidents";let entries=JSON.parse(localStorage.getItem(key)||"[]");function render(){entries.forEach((e,i)=>{if(document.querySelector(`[data-new="${i}"]`))return;const tr=document.createElement("tr");tr.dataset.new=i;const folio="SSH-"+String(27+i).padStart(3,"0");tr.innerHTML=`<td><b>${folio}</b><small>28 sep 2026</small></td><td>${escapeHtml(e.description)}</td><td>${escapeHtml(e.area)}</td><td>${escapeHtml(e.contractor)}</td><td><span class="status open">Abierto</span></td>`;rows.prepend(tr)});document.querySelector("#openCount").textContent=String(3+entries.length).padStart(2,"0")}function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}document.querySelector("#newIncident").addEventListener("click",()=>dlg.showModal());document.querySelector("#showAll").addEventListener("click",()=>document.querySelector("#incidentes").scrollIntoView({behavior:"smooth"}));form.addEventListener("submit",e=>{if(e.submitter?.id!=="saveIncident")return;e.preventDefault();entries.push({description:document.querySelector("#description").value,area:document.querySelector("#area").value,contractor:document.querySelector("#contractor").value,priority:document.querySelector("#priority").value});localStorage.setItem(key,JSON.stringify(entries));render();form.reset();dlg.close()});render()})();